private val scheduleNames=listOf("daily" to "每天","weekdays" to "工作日","weekly" to "每周","once" to "仅一次","cron" to "自定义","manual" to "手动触发")
private val weekNames=listOf("monday" to "周一","tuesday" to "周二","wednesday" to "周三","thursday" to "周四","friday" to "周五","saturday" to "周六","sunday" to "周日")
private fun rovaiScheduleLabel(schedule:JsonObject):String=when(schedule.coreText("kind")){"manual"->"手动触发";"daily"->"每天 "+schedule.coreText("at");"weekdays"->"工作日 "+schedule.coreText("at");"weekly"->"每周 "+(weekNames.firstOrNull{it.first==schedule.coreText("weekday")}?.second?:"")+" "+schedule.coreText("at");"once"->schedule.coreText("date")+" "+schedule.coreText("at");"cron"->"自定义 · "+schedule.coreText("expression");else->"未识别的计划"}
/** Rovai AutomationWorkspace/Editor fields and history using Codeg native GlassRow. */
@Composable
fun RovaiAutomationSettings(model:RovaiWorkspaceViewModel,onOpenThread:(String)->Unit){
    val state by model.state.collectAsStateWithLifecycle();val scope=rememberCoroutineScope()
    var entries by remember{mutableStateOf<List<JsonObject>>(emptyList())};var cursor by remember{mutableStateOf<String?>(null)};var filter by remember{mutableStateOf("all")};var search by remember{mutableStateOf("")}
    var selected by remember{mutableStateOf<JsonObject?>(null)};var creating by remember{mutableStateOf(false)};var busy by remember{mutableStateOf(false)};var issue by remember{mutableStateOf<String?>(null)};var confirm by remember{mutableStateOf<Pair<RovaiOperation,JsonObject>?>(null)}
    var history by remember{mutableStateOf<JsonObject?>(null)};var runs by remember{mutableStateOf<List<JsonObject>>(emptyList())};var runCursor by remember{mutableStateOf<String?>(null)}
    suspend fun load(after:String?=null){busy=true;try{val value=model.query(RovaiOperation.AUTOMATIONS_LIST,buildJsonObject{put("status",filter);put("query",search);put("limit",30);after?.let{put("cursor",it)}}).coreObject();entries=if(after==null)value["automations"].coreArray()else entries+value["automations"].coreArray();cursor=(value["nextCursor"] as? JsonPrimitive)?.contentOrNull;issue=null}catch(cancelled:CancellationException){throw cancelled}catch(error:Exception){issue=error.message}finally{busy=false}}
    suspend fun readRuns(item:JsonObject,after:String?=null){busy=true;try{val value=model.query(RovaiOperation.AUTOMATIONS_RUNS_LIST,buildJsonObject{put("automationId",item.coreText("automationId"));put("limit",20);after?.let{put("cursor",it)}}).coreObject();runs=if(after==null)value["runs"].coreArray()else runs+value["runs"].coreArray();runCursor=(value["nextCursor"] as? JsonPrimitive)?.contentOrNull;history=item;issue=null}catch(cancelled:CancellationException){throw cancelled}catch(error:Exception){issue=error.message}finally{busy=false}}
    LaunchedEffect(filter,state.lastResult,state.resourceVersion){delay(250);if(!creating&&selected==null)load();history?.let{readRuns(it)}}
    if(creating||selected!=null){RovaiAutomationEditor(model,selected,onSaved={selected=null;creating=false},onClose={selected=null;creating=false});return}
    Column(Modifier.fillMaxSize().padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){
        Row{Text("定时任务",style=MaterialTheme.typography.titleLarge,modifier=Modifier.weight(1f));TextButton(enabled=state.pending==null,onClick={creating=true}){Text("新建")}}
        issue?.let{Text(it,color=CodegTheme.colors.danger)};if(busy)LinearProgressIndicator(Modifier.fillMaxWidth())
        if(history!=null){Row{Text(history!!.coreText("name"),Modifier.weight(1f));TextButton(onClick={history=null;runs=emptyList()}){Text("返回列表")}};LazyColumn(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(8.dp)){items(runs,key={it.coreText("runId")}){run->GlassRow{Text(run.coreText("scheduledFor"));Text(run.coreText("status"),color=CodegTheme.colors.textSecondary);if(run.coreText("reason").isNotEmpty())Text(run.coreText("reason"));Row{if(run.coreText("threadId").isNotEmpty())TextButton(onClick={onOpenThread(run.coreText("threadId"))}){Text("打开结果对话")};if(run.coreText("status") in listOf("running","cancelling"))TextButton(enabled=state.pending==null,onClick={confirm=RovaiOperation.AUTOMATIONS_CANCELRUN to buildJsonObject{put("automationId",history!!.coreText("automationId"));put("runId",run.coreText("runId"))}}){Text("停止本次运行")}}}};runCursor?.let{after->item{TextButton(enabled=!busy,onClick={scope.launch{readRuns(history!!,after)}}){Text("更早的运行")}}}}}
        else{
            OutlinedTextField(search,{search=it},label={Text("搜索任务")},modifier=Modifier.fillMaxWidth(),trailingIcon={TextButton(enabled=!busy,onClick={scope.launch{load()}}){Text("搜索")}})
            Row(Modifier.horizontalScroll(rememberScrollState())){listOf("all" to "全部","enabled" to "启用","closed" to "已关闭").forEach{(id,label)->FilterChip(selected=filter==id,onClick={filter=id},label={Text(label)})}}
            LazyColumn(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(10.dp)){items(entries,key={it.coreText("automationId")}){item->GlassRow{Text(item.coreText("name"),style=MaterialTheme.typography.titleMedium);Text(item.coreText("prompt"),maxLines=3);Text(rovaiScheduleLabel(item["schedule"].coreObject()),color=CodegTheme.colors.textSecondary);Text("下次 · "+item.coreText("nextRunAt"),style=MaterialTheme.typography.labelSmall);Row(Modifier.horizontalScroll(rememberScrollState())){TextButton(enabled=state.pending==null,onClick={selected=item}){Text("编辑")};TextButton(enabled=!busy,onClick={scope.launch{readRuns(item)}}){Text("运行记录")};TextButton(enabled=state.pending==null,onClick={confirm=RovaiOperation.AUTOMATIONS_RUN to buildJsonObject{put("automationId",item.coreText("automationId"))}}){Text("立即运行")};TextButton(enabled=state.pending==null,onClick={confirm=(if(item["enabled"]==JsonPrimitive(true))RovaiOperation.AUTOMATIONS_CLOSE else RovaiOperation.AUTOMATIONS_UPDATE) to buildJsonObject{put("automationId",item.coreText("automationId"));put("expectedVersion",item.coreLong("version"));if(item["enabled"]!=JsonPrimitive(true))put("enabled",true)}}){Text(if(item["enabled"]==JsonPrimitive(true))"关闭" else "启用")};TextButton(enabled=state.pending==null,onClick={confirm=RovaiOperation.AUTOMATIONS_DELETE to buildJsonObject{put("automationId",item.coreText("automationId"));put("expectedVersion",item.coreLong("version"))}}){Text("删除")}}}};cursor?.let{after->item{TextButton(enabled=!busy,onClick={scope.launch{load(after)}}){Text("加载更多")}}}}
        }
    }
    confirm?.let{action->AlertDialog(onDismissRequest={confirm=null},title={Text(if(action.first==RovaiOperation.AUTOMATIONS_RUN)"立即运行此任务？"else if(action.first==RovaiOperation.AUTOMATIONS_DELETE)"删除定时任务？"else if(action.first==RovaiOperation.AUTOMATIONS_CANCELRUN)"停止所选运行？"else"修改任务启用状态？")},text={Text(if(action.first==RovaiOperation.AUTOMATIONS_RUN)"会在宿主创建一次实际执行。"else"按当前所选任务和版本执行；运行结果仍保留在原对话中。")},confirmButton={TextButton(enabled=state.pending==null&&!state.busy,onClick={model.command(action.first,action.second);confirm=null}){Text("确认")}},dismissButton={TextButton(onClick={confirm=null}){Text("取消")}})}
}
@Composable
private fun RovaiAutomationEditor(model:RovaiWorkspaceViewModel,original:JsonObject?,onSaved:()->Unit,onClose:()->Unit){
    val state by model.state.collectAsStateWithLifecycle();val scope=rememberCoroutineScope();val id=original?.coreText("automationId")?:"new";val owner="automation-draft:$id"
    var name by remember(id){mutableStateOf(original?.coreText("name")?:"")};var prompt by remember(id){mutableStateOf(original?.coreText("prompt")?:"")};var member by remember(id){mutableStateOf(original?.coreText("memberId")?:"")};var path by remember(id){mutableStateOf(original?.get("projectRef").coreObject().coreText("path"))}
    var kind by remember(id){mutableStateOf(original?.get("schedule").coreObject().coreText("kind").ifEmpty{"daily"})};var at by remember(id){mutableStateOf(original?.get("schedule").coreObject().coreText("at").ifEmpty{"09:00"})};var date by remember(id){mutableStateOf(original?.get("schedule").coreObject().coreText("date"))};var weekday by remember(id){mutableStateOf(original?.get("schedule").coreObject().coreText("weekday").ifEmpty{"monday"})};var cron by remember(id){mutableStateOf(original?.get("schedule").coreObject().coreText("expression"))}
    var channels by remember(id){mutableStateOf((original?.get("notifyChannels") as? JsonArray)?.map{it.jsonPrimitive.content}?.toSet()?:emptySet())};var ready by remember(id){mutableStateOf(false)};var issue by remember{mutableStateOf<String?>(null)};var sent by remember{mutableStateOf<String?>(null)}
    fun draft():JsonObject=buildJsonObject{put("name",name);put("prompt",prompt);put("memberId",member);put("path",path);put("kind",kind);put("at",at);put("date",date);put("weekday",weekday);put("cron",cron);put("channels",JsonArray(channels.map(::JsonPrimitive)))}
    LaunchedEffect(id){try{val raw=model.readBody(owner);if(raw.isNotEmpty()){val value=Json.parseToJsonElement(raw).coreObject();name=value.coreText("name");prompt=value.coreText("prompt");member=value.coreText("memberId");path=value.coreText("path");kind=value.coreText("kind");at=value.coreText("at");date=value.coreText("date");weekday=value.coreText("weekday");cron=value.coreText("cron");channels=value["channels"].jsonArray.map{it.jsonPrimitive.content}.toSet()};ready=true}catch(error:Exception){issue=error.message}}
    val current=draft().toString();LaunchedEffect(current,ready){if(ready)try{model.saveBody(owner,current)}catch(error:Exception){issue=error.message}}
    LaunchedEffect(state.lastResult){val receipt=state.lastResult.coreObject()["commandResult"].coreObject().ifEmpty{state.lastResult.coreObject()};if(sent!=null&&receipt.coreText("commandId")==sent&&receipt.coreText("status") in listOf("applied","accepted")){model.saveBody(owner,"");onSaved()}}
    val blocked=!ready||state.pending!=null||state.busy
    LazyColumn(Modifier.fillMaxSize().padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){
        item{Row{Text(if(original==null)"新建定时任务"else"编辑定时任务",Modifier.weight(1f),style=MaterialTheme.typography.titleLarge);TextButton(onClick=onClose){Text("返回，保留草稿")}};issue?.let{Text(it,color=CodegTheme.colors.danger)}}
        item{OutlinedTextField(name,{name=it},label={Text("名称")},enabled=!blocked,modifier=Modifier.fillMaxWidth());OutlinedTextField(prompt,{prompt=it},label={Text("任务内容")},enabled=!blocked,minLines=4,modifier=Modifier.fillMaxWidth())}
        item{Text("执行队员");state.members.filter{it.coreText("presence")=="present"}.forEach{agent->Row{RadioButton(selected=member==agent.coreText("agentId"),enabled=!blocked,onClick={member=agent.coreText("agentId")});Text(agent.coreText("displayName"))}};Text("工作目录");Row{RadioButton(selected=path.isEmpty(),enabled=!blocked,onClick={path=""});Text("快速对话")};state.navigation["projects"].coreArray().forEach{project->Row{RadioButton(selected=path==project.coreText("projectPath"),enabled=!blocked,onClick={path=project.coreText("projectPath")});Text(project.coreText("name"))}}}
        item{Row(Modifier.horizontalScroll(rememberScrollState())){scheduleNames.forEach{(value,label)->FilterChip(selected=kind==value,enabled=!blocked,onClick={kind=value},label={Text(label)})}};if(kind !in listOf("manual","cron"))OutlinedTextField(at,{at=it},label={Text("时间 HH:mm（宿主时区）")},enabled=!blocked);if(kind=="once")OutlinedTextField(date,{date=it},label={Text("日期 yyyy-MM-dd")},enabled=!blocked);if(kind=="weekly")Row(Modifier.horizontalScroll(rememberScrollState())){weekNames.forEach{(value,label)->FilterChip(selected=weekday==value,enabled=!blocked,onClick={weekday=value},label={Text(label)})}};if(kind=="cron")OutlinedTextField(cron,{cron=it},label={Text("Cron：分钟 小时 日期 月份 星期")},enabled=!blocked)}
        item{Text("结果通知");listOf("feishu" to "飞书","lark" to "Lark","dingtalk" to "钉钉").forEach{(value,label)->Row{Checkbox(checked=value in channels,enabled=!blocked,onCheckedChange={channels=if(it)channels+value else channels-value});Text(label)}}}
        item{Button(enabled=!blocked&&prompt.isNotBlank()&&member.isNotEmpty(),onClick={scope.launch{try{if(kind !in listOf("manual","cron"))require(Regex("([01][0-9]|2[0-3]):[0-5][0-9]").matches(at)){"请填写有效时间"};if(kind=="once")java.time.LocalDate.parse(date);if(kind=="cron")require(cron.trim().split(Regex("\\s+")).size==5){"Cron需要5个字段"};model.saveBody(owner,current);val command=buildJsonObject{if(original!=null){put("automationId",id);put("expectedVersion",original.coreLong("version"))};put("name",name);put("prompt",prompt);put("memberId",member);putJsonObject("projectRef"){put("kind",if(path.isEmpty())"quick_chat"else"directory");if(path.isNotEmpty())put("path",path)};putJsonObject("schedule"){put("kind",kind);if(kind !in listOf("manual","cron"))put("at",at);if(kind=="once")put("date",date);if(kind=="weekly")put("weekday",weekday);if(kind=="cron")put("expression",cron)};put("notifyChannels",JsonArray(channels.map(::JsonPrimitive)))};val commandId=UUID.randomUUID().toString();sent=commandId;model.execute(if(original==null)RovaiOperation.AUTOMATIONS_CREATE else RovaiOperation.AUTOMATIONS_UPDATE,buildJsonObject{put("commandId",commandId);put("command",command)})}catch(error:Exception){issue=error.message}}}){Text("保存任务")}}
    }
}
